proof.text:
@prefix d: <urn:c2sim-validation-demo:> .
@prefix math: <http://www.w3.org/2000/10/swap/math#> .
@prefix pe: <https://eyereasoner.github.io/pe#> .
@prefix rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#> .

d:requestA a d:PassesDemonstratedChecks .
d:requestB d:issue d:UnresolvedRecipient .
d:requestB d:issue d:EndBeforeStart .

{ d:requestA a d:PassesDemonstratedChecks . } pe:why {
  { d:requestA a d:PassesDemonstratedChecks . }
    pe:by [ pe:rule "session-program"; pe:line 1 ];
    pe:binding
      [ pe:var "e"; pe:value 20 ],
      [ pe:var "r"; pe:value d:requestA ],
      [ pe:var "s"; pe:value 10 ];
    pe:uses
      { d:requestA a d:SimulationRequest . },
      { d:requestA d:recipientResolved true . },
      { d:requestA d:startMinute 10 . },
      { d:requestA d:endMinute 20 . },
      { 10 math:lessThan 20 . }.

  { d:requestA a d:SimulationRequest . }
    pe:by [ pe:fact "<unknown>" ].

  { d:requestA d:recipientResolved true . }
    pe:by [ pe:fact "<unknown>" ].

  { d:requestA d:startMinute 10 . }
    pe:by [ pe:fact "<unknown>" ].

  { d:requestA d:endMinute 20 . }
    pe:by [ pe:fact "<unknown>" ].

  { 10 math:lessThan 20 . }
    pe:by [ pe:builtin math:lessThan ].
}.

{ d:requestB d:issue d:UnresolvedRecipient . } pe:why {
  { d:requestB d:issue d:UnresolvedRecipient . }
    pe:by [ pe:rule "session-program"; pe:line 1 ];
    pe:binding [ pe:var "r"; pe:value d:requestB ];
    pe:uses
      { d:requestB a d:SimulationRequest . },
      { d:requestB d:recipientResolved false . }.

  { d:requestB a d:SimulationRequest . }
    pe:by [ pe:fact "<unknown>" ].

  { d:requestB d:recipientResolved false . }
    pe:by [ pe:fact "<unknown>" ].
}.

{ d:requestB d:issue d:EndBeforeStart . } pe:why {
  { d:requestB d:issue d:EndBeforeStart . }
    pe:by [ pe:rule "session-program"; pe:line 1 ];
    pe:binding
      [ pe:var "e"; pe:value 10 ],
      [ pe:var "r"; pe:value d:requestB ],
      [ pe:var "s"; pe:value 20 ];
    pe:uses
      { d:requestB a d:SimulationRequest . },
      { d:requestB d:startMinute 20 . },
      { d:requestB d:endMinute 10 . },
      { 20 math:greaterThan 10 . }.

  { d:requestB a d:SimulationRequest . }
    pe:by [ pe:fact "<unknown>" ].

  { d:requestB d:startMinute 20 . }
    pe:by [ pe:fact "<unknown>" ].

  { d:requestB d:endMinute 10 . }
    pe:by [ pe:fact "<unknown>" ].

  { 20 math:greaterThan 10 . }
    pe:by [ pe:builtin math:greaterThan ].
}.
